import {icon} from './icons.js';
import {STORAGE_KEY,stages,owners,layouts,newId,initialState,loadState,getField,getFields,companyFor,rawValue,labelValue,setValue,findRule,removeRule,ruleCount,recordsFor,boardGroups,newView} from './model.js';

let state=loadState();
const history=[];
const ui={search:'',selected:new Set(),detailId:null,detailSource:null,popover:null,dialogKind:null,newLayout:'table',mobile:false,toastTimer:null,timelineStart:'2026-10-05',dragField:null};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('ko-KR').format(Number(v)||0);
const compact=v=>Number(v)>=100000000?`${(Number(v)/100000000).toFixed(1)}억`:`${money(Math.round(Number(v)/10000))}만`;
const activeView=()=>state.views.find(v=>v.id===state.activeView)||state.views[0];
const isDashboard=()=>state.activeView==='dashboard';
const activeRecords=()=>recordsFor(state,activeView(),ui.search);
const recordById=(id,source=activeView().sourceId)=>source==='companies'?state.companies.find(r=>r.id===id):state.deals.find(r=>r.id===id);
const options=(items,value)=>items.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.label)}</option>`).join('');
const visibleProps=view=>view.props.filter(p=>!p.hidden&&getField(state,p.fieldId));
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('브라우저 저장 공간을 확인해 주세요.');}}
function mutate(fn,message,refresh=true){history.push(JSON.stringify(state));if(history.length>40)history.shift();fn();persist();if(refresh)render();if(message)toast(message,true);savedFlash();}
function savedFlash(){const el=$('#saved-text');if(!el)return;el.textContent='저장됨';setTimeout(()=>{if($('#saved-text'))$('#saved-text').textContent='모든 변경사항 저장됨';},1400);}
function toast(message,undo=false){clearTimeout(ui.toastTimer);$('#toast').innerHTML=`${esc(message)}${undo?'<button data-action="undo">되돌리기</button>':''}`;$('#toast').classList.add('visible');ui.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function undo(){if(!history.length){toast('되돌릴 변경사항이 없어요.');return;}state=JSON.parse(history.pop());ui.selected.clear();persist();closePopover();render();toast('이전 상태로 되돌렸어요.');}
function chooseView(id){const view=state.views.find(v=>v.id===id);if(!view)return;state.activeView=id;state.sourceId=view.sourceId;ui.search='';ui.selected.clear();ui.mobile=false;closePopover();closeDetail();persist();render();}
function chooseSource(id){chooseView(state.views.find(v=>v.sourceId===id)?.id);}
function nameFor(view){return view.sourceId==='companies'?'회사':view.sourceId==='sales'?'영업 기회':'진행 중 영업';}
function companyMark(record,small=false){const c=record.companyName?record:companyFor(state,record);return `<span class="company-mark ${small?'small':''}" style="background:${esc(c?.color||'#eceff5')}">${esc(c?.initial||record.name?.[0]||'+')}</span>`;}
function ownerAvatar(id,large=false){const o=owners.find(x=>x.id===id)||owners[0];return `<span class="avatar ${large?'large':''}" style="background:${o.color}" title="${o.label}">${o.initials}</span>`;}
function displayValue(record,fieldId,prop={}){
 const field=getField(state,fieldId),raw=rawValue(state,record,fieldId);
 if(fieldId==='company'){const c=companyFor(state,record);return c?`<span class="company-chip">${companyMark(c,true)}${esc(c.companyName)}</span>`:'<span class="cell-muted">고객사 추가</span>';}
 if(field?.type==='status'){const option=field.options?.find(o=>o.id===raw);return option?`<span class="pill" style="background:${option.tint};color:${option.color}"><span class="stage-dot" style="background:${option.color};width:5px;height:5px"></span>${esc(option.label)}</span>`:'<span class="cell-muted">미지정</span>';}
 if(field?.type==='person'){const o=owners.find(x=>x.id===raw);return o?`${ownerAvatar(raw)}<span>${esc(o.label)}</span>`:'<span class="cell-muted">담당자 지정</span>';}
 if(field?.type==='multiselect'){const tints=['#f1eddc','#e5f1ef','#e9edf9','#f5e5ec'];return `<span class="pills">${(Array.isArray(raw)?raw:[]).map((v,i)=>`<span class="pill" style="background:${tints[i%4]};color:#8c8e91">${esc(v)}</span>`).join('')||'<span class="cell-muted">—</span>'}</span>`;}
 if(field?.type==='currency')return `<span class="cell-money">${raw!==''&&raw!=null?money(raw)+(prop.decimals?'.00':'')+'원':'—'}</span>`;
 if(field?.type==='date')return raw?`<span>${Number(String(raw).slice(5,7))}월 ${Number(String(raw).slice(8,10))}일</span>`:'<span class="cell-muted">날짜 추가</span>';
 if(field?.type==='checkbox')return raw?'✓':'—';
 return `<span class="${fieldId==='domain'?'cell-link':''}">${esc(raw)||'<span class="cell-muted">—</span>'}</span>`;
}
function renderSidebar(){
 $('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">↗</div><div><div class="brand-name">OneHand CRM</div><div class="workspace-name">우리의 업무 공간</div></div>${icon('chevron',12)}</div>
 <button class="quick-search" data-action="quick-search">${icon('search',14)}빠르게 찾기<span class="kbd">⌘ K</span></button>
 <button class="nav-item ${isDashboard()?'active':''}" data-action="dashboard"><span class="nav-icon">${icon('dashboard')}</span>업무 요약</button>
 <div class="nav-section">관리하는 정보</div>
 <button class="nav-item ${!isDashboard()&&state.sourceId==='companies'?'active':''}" data-action="source" data-id="companies"><span class="nav-icon">${icon('company')}</span>회사<span class="nav-count">${state.companies.length}</span></button>
 <button class="nav-item ${!isDashboard()&&state.sourceId==='sales'?'active':''}" data-action="source" data-id="sales"><span class="nav-icon">${icon('briefcase')}</span>영업 기회<span class="nav-count">${state.deals.length}</span></button>
 <div class="nav-section">업무 목록</div>
 <button class="nav-item ${!isDashboard()&&state.sourceId==='pipeline'?'active':''}" data-action="source" data-id="pipeline"><span class="nav-icon">${icon('layers')}</span>진행 중 영업<span class="nav-count">${state.deals.length}</span></button>
 <div class="nav-section">즐겨찾는 보기</div>
 ${state.views.filter(v=>v.sourceId==='pipeline').slice(0,6).map(v=>`<button class="nav-item nav-inset" data-action="choose-view" data-id="${v.id}"><span class="nav-icon">${icon(layouts.find(l=>l.id===v.layout)?.icon||'table',14)}</span>${esc(v.name)}</button>`).join('')}
 <div class="nav-spacer"></div><button class="nav-item" data-action="help"><span class="nav-icon">${icon('right')}</span>목업 둘러보기</button>
 <div class="preview-note"><span class="dot"></span>UX 미리보기 · 예시 데이터</div>
 <div class="profile">${ownerAvatar('jason',true)}<div class="profile-info">송재근<small>나의 업무 공간</small></div><button class="icon-btn" data-action="help" aria-label="미리보기 안내">${icon('dots')}</button></div>`;
}
function renderHeader(){const view=activeView();$('#page-header').innerHTML=`<button class="icon-btn mobile-toggle" data-action="mobile" aria-label="메뉴 열기">${icon('menu')}</button><span style="color:#7b91c7">${icon(isDashboard()?'dashboard':view.sourceId==='companies'?'company':view.sourceId==='sales'?'briefcase':'layers',17)}</span><span class="page-heading">${isDashboard()?'업무 요약':nameFor(view)}</span>${!isDashboard()&&view.sourceId==='pipeline'?'<span class="source-badge">'+icon('briefcase',11)+'영업 기회</span>':''}<div class="header-right"><span class="saved-indicator">${icon('check',12)}<span id="saved-text">모든 변경사항 저장됨</span></span><span class="subtle-label">나의 업무 공간</span>${ownerAvatar('jason')}</div>`;}
function renderBars(){
 if(isDashboard()){$('#view-bar').style.display='none';$('#toolbar').style.display='none';return;}
 $('#view-bar').style.display='flex';$('#toolbar').style.display='flex';
 const view=activeView();
 $('#view-bar').innerHTML=`<div class="view-tabs">${state.views.filter(v=>v.sourceId===view.sourceId).map(v=>`<button class="view-tab ${v.id===view.id?'active':''}" data-action="choose-view" data-id="${v.id}" ${v.id===view.id?'aria-current="page"':''}>${icon(layouts.find(l=>l.id===v.layout)?.icon||'table',13)}${esc(v.name)}</button>`).join('')}</div><button class="button quiet add-view-button" data-action="new-view" aria-label="보기 추가">${icon('plus',14)}<span class="add-view-label">보기</span></button><div class="bar-actions"><button class="button" data-action="settings">${icon('settings',14)}<span class="settings-label">보기 설정</span>${icon('chevron',11)}</button><button class="button primary" data-action="new-record">${icon('plus',14)}<span class="new-record-label">${view.sourceId==='companies'?'회사':'영업'} 추가</span></button></div>`;
 const count=ruleCount(view.filter);
 $('#toolbar').innerHTML=`<button class="button ${count?'active':''}" data-action="filter">${icon('filter',13)}필터${count?`<span>${count}</span>`:''}</button><button class="button ${view.sorts.length?'active':''}" data-action="sort">${icon('sort',13)}${view.sorts.length?`${esc(getField(state,view.sorts[0].fieldId)?.label||'')}순`:'정렬'}</button>${view.layout==='board'?`<button class="button" data-action="group">${icon('group',13)}${esc(getField(state,view.groupBy)?.label||'단계')}별</button>`:''}${count?`<span class="filter-summary">${filterText(view.filter)}</span>`:''}<label class="search-box">${icon('search',13)}<input id="record-search" aria-label="현재 목록 검색" placeholder="검색" value="${esc(ui.search)}"></label>`;
 $('#record-search').addEventListener('input',e=>{ui.search=e.target.value;renderWorkspace();renderStatus();});
}
function filterText(group){return group.rules.map(r=>r.rules?`(${filterText(r)})`:`${esc(getField(state,r.fieldId)?.label||'')} ${r.op==='gte'?'≥':r.op==='lte'?'≤':r.op==='neq'?'≠':r.op==='contains'?'포함':'='} ${esc(getField(state,r.fieldId)?.options?.find(o=>o.id===r.value)?.label||r.value||'비어 있음')}`).join(group.operator==='AND'?' · ':' 또는 ');}
function renderTable(view,embedded=false){
 const records=recordsFor(state,view,embedded?'':ui.search),properties=visibleProps(view);
 if(!records.length)return emptyState(view);
 return `<table class="data-table"><thead><tr><th>${embedded?'':`<input type="checkbox" aria-label="현재 기록 모두 선택" data-action="select-all" ${records.every(r=>ui.selected.has(r.id))?'checked':''}>`}</th>${properties.map(p=>`<th style="width:${p.width||180}px;min-width:${p.width||180}px" draggable="${!embedded}" data-field-id="${p.fieldId}"><button data-action="field-menu" data-field="${p.fieldId}" data-view="${view.id}">${icon(getField(state,p.fieldId)?.icon,13)}${esc(p.label||getField(state,p.fieldId)?.label)}${icon('chevron',10)}</button></th>`).join('')}${embedded?'':'<th style="width:60px"><button data-action="new-field" aria-label="정보 추가">'+icon('plus',15)+'</button></th>'}</tr></thead><tbody>${records.map(r=>`<tr class="${ui.selected.has(r.id)?'selected':''}"><td>${embedded?'':`<input type="checkbox" aria-label="${esc(r.name||r.companyName)} 선택" data-action="select-record" data-id="${r.id}" ${ui.selected.has(r.id)?'checked':''}>`}</td>${properties.map((p,i)=>`<td><button class="cell-button ${i===0?'cell-title':''}" data-action="${i===0?'detail':'edit-cell'}" data-id="${r.id}" data-field="${p.fieldId}" data-source="${view.sourceId}">${i===0?companyMark(r):''}${displayValue(r,p.fieldId,p)}</button></td>`).join('')}${embedded?'':'<td></td>'}</tr>`).join('')}</tbody></table>${embedded?'':`<button class="table-add-row" data-action="new-record">${icon('plus',14)}새 ${view.sourceId==='companies'?'회사':'영업'} 추가</button>`}`;
}
function emptyState(view){return `<div class="empty-state">${icon('search',30)}<h3>표시할 기록이 없어요</h3><p>검색어나 필터를 바꾸면 다른 기록을 볼 수 있어요.</p><button class="button" data-action="clear-filters" data-view="${view.id}">필터 초기화</button></div>`;}
function renderBoard(view,embedded=false){
 const records=recordsFor(state,view,embedded?'':ui.search),groups=boardGroups(state,view),properties=visibleProps(view),title=properties.find(p=>p.role==='TITLE')||properties[0],body=properties.filter(p=>p!==title);
 return `<div class="board" data-view="${view.id}">${groups.filter(g=>!g.hidden).map(g=>{
  const cards=records.filter(r=>r[view.groupBy]===g.id),count=cards.length;
  if(g.folded)return `<section class="board-column folded" data-stage="${g.id}" data-view="${view.id}"><div class="folded-label"><button data-action="fold-group" data-stage="${g.id}" data-view="${view.id}" aria-label="${esc(g.label)} 펼치기">${icon('right',13)}</button><span class="stage-dot" style="background:${g.color}"></span>${esc(g.label)}<span class="count-badge">${count}</span></div></section>`;
  return `<section class="board-column" data-stage="${g.id}" data-view="${view.id}"><header class="column-header" draggable="${!embedded}" data-group-drag="${g.id}"><span class="stage-dot" style="background:${g.color}"></span><span class="stage-name">${esc(g.label)}</span><span class="count-badge">${count}</span><button class="icon-btn" data-action="group-menu" data-stage="${g.id}" data-view="${view.id}" aria-label="${esc(g.label)} 열 설정">${icon('dots',14)}</button></header><div class="column-cards">${cards.map(r=>`<article class="deal-card" draggable="true" data-record-drag="${r.id}" data-view="${view.id}"><div class="card-title">${companyMark(r)}<button data-action="detail" data-id="${r.id}" data-source="${view.sourceId}">${esc(labelValue(state,r,title?.fieldId||'name'))}</button></div>${body.map(p=>`<div class="card-field">${icon(getField(state,p.fieldId)?.icon,13)}${view.showLabels?`<span class="card-field-label">${esc(p.label||getField(state,p.fieldId)?.label)}</span>`:''}<span class="card-field-value">${displayValue(r,p.fieldId,p)}</span></div>`).join('')}<div class="card-footer">${ownerAvatar(r.owner)}<span style="font-size:8px;color:#a6acb7">${esc(owners.find(o=>o.id===r.owner)?.label||'')}</span><span class="card-date">${icon('date',11)}${esc(r.end?`${Number(r.end.slice(5,7))}.${Number(r.end.slice(8,10))}`:'예정일 미지정')}</span></div></article>`).join('')}<button class="column-add" data-action="new-record" data-stage="${g.id}">${icon('plus',12)}영업 추가</button></div><footer class="column-total"><span>예상 매출 합계</span><strong>${compact(cards.reduce((sum,r)=>sum+Number(r.amount||0),0))}원</strong></footer></section>`;
 }).join('')}${embedded?'':`<div class="board-end"><button data-action="add-stage" aria-label="영업 단계 추가">${icon('plus',15)}</button>${groups.some(g=>g.hidden)?'<div class="hidden-groups-hint"><button data-action="group">숨긴 열 보기</button></div>':''}</div>`}</div>`;
}
function chartContent(view){
 const records=recordsFor(state,view,ui.search);
 if(view.sourceId==='companies'){
  const categories=[...new Set(records.flatMap(r=>r.companyIndustry||[]))],groups=categories.map(label=>({label,total:records.filter(r=>r.companyIndustry?.includes(label)).length})),max=Math.max(...groups.map(g=>g.total),1);
  return `<div class="chart-container"><h3>업종별 회사 수</h3><div class="bar-chart company-chart">${groups.map((g,i)=>`<div class="chart-bar-wrap"><div class="chart-bar-value">${g.total}개</div><button class="chart-bar" style="height:${g.total/max*100}%;background:${['#8b94d9','#75bfa5','#e8b877','#c49bbb'][i%4]}" data-action="chart-industry" data-value="${esc(g.label)}" title="${esc(g.label)} ${g.total}개"><span class="chart-bar-label">${esc(g.label)}</span></button></div>`).join('')}</div></div>`;
 }
 const groups=(getField(state,'stage')?.options||stages).map(s=>({...s,total:records.filter(r=>r.stage===s.id).reduce((n,r)=>n+Number(r.amount||0),0)})),max=Math.max(...groups.map(g=>g.total),1);return `<div class="chart-container"><h3>단계별 예상 매출</h3><div class="bar-chart">${groups.map(g=>`<div class="chart-bar-wrap"><div class="chart-bar-value">${compact(g.total)}원</div><button class="chart-bar" style="height:${Math.max(3,g.total/max*100)}%;background:${g.color}" data-action="chart-stage" data-stage="${g.id}" title="${g.label} ${money(g.total)}원"><span class="chart-bar-label">${esc(g.label)}</span></button></div>`).join('')}</div></div>`;
}
function renderChart(view){const records=recordsFor(state,view,ui.search),total=records.reduce((n,r)=>n+Number(r.amount||0),0),won=records.filter(r=>r.stage==='won').reduce((n,r)=>n+Number(r.amount||0),0);if(view.sourceId==='companies')return `<div class="chart-page"><div class="chart-header"><div><h2>고객사를 한눈에</h2><p>업종을 누르면 해당 회사 목록으로 이동합니다.</p></div></div><div class="metrics"><div class="metric"><div class="metric-label">관리 중인 회사</div><div class="metric-value">${records.length}<small>개</small></div></div><div class="metric"><div class="metric-label">업종</div><div class="metric-value">${new Set(records.flatMap(r=>r.companyIndustry||[])).size}<small>개</small></div></div></div>${chartContent(view)}</div>`;return `<div class="chart-page"><div class="chart-header"><div><h2>영업의 흐름을 한눈에</h2><p>현재 보기의 필터를 적용한 영업 기록을 보여줍니다.</p></div><span class="subtle-label">2026년 10월</span></div><div class="metrics"><div class="metric"><div class="metric-label">전체 예상 매출</div><div class="metric-value">${compact(total)}<small>원</small></div><div class="metric-foot">현재 보기 ${records.length}건의 합계</div></div><div class="metric"><div class="metric-label">계약 완료 매출</div><div class="metric-value">${compact(won)}<small>원</small></div><div class="metric-foot">계약 단계의 영업</div></div><div class="metric"><div class="metric-label">영업 기회</div><div class="metric-value">${records.length}<small>건</small></div><div class="metric-foot">현재 필터와 검색 기준</div></div></div>${chartContent(view)}</div>`;}
function renderTimeline(view){const records=recordsFor(state,view,ui.search),start=new Date(ui.timelineStart+'T00:00:00Z'),days=Array.from({length:28},(_,i)=>new Date(start.getTime()+i*86400000)),left=window.innerWidth<=700?180:250;
 return `<div class="timeline-intro"><strong>${start.getUTCMonth()+1}월 ${start.getUTCFullYear()}</strong><span>기록을 눌러 일정과 선행 업무를 설정해 보세요.</span><span class="spacer"></span><button class="icon-btn" data-action="timeline-shift" data-days="-7" aria-label="이전 주">${icon('left',13)}</button><button class="icon-btn" data-action="timeline-shift" data-days="7" aria-label="다음 주">${icon('right',13)}</button></div><div class="timeline"><div class="timeline-header"><div class="timeline-title">영업 기회</div>${days.map(d=>`<div class="timeline-day ${[0,6].includes(d.getUTCDay())?'weekend':''}">${['일','월','화','수','목','금','토'][d.getUTCDay()]}<strong>${d.getUTCDate()}</strong></div>`).join('')}</div>${records.map(r=>{const from=Math.floor((new Date(r.start+'T00:00:00Z')-start)/86400000),to=Math.floor((new Date(r.end+'T00:00:00Z')-start)/86400000),a=Math.max(0,from),b=Math.min(27,to),incoming=state.dependencies.filter(d=>d.targetId===r.id);return `<div class="timeline-row"><button class="timeline-title" data-action="detail" data-id="${r.id}">${companyMark(r,true)}${esc(r.name)}${incoming.length?'<span class="timeline-dep-indicator">'+icon('link',12)+'</span>':''}</button>${days.map(d=>`<div class="timeline-cell ${[0,6].includes(d.getUTCDay())?'weekend':''}"></div>`).join('')}${b>=a?`<button class="timeline-bar" style="left:${left+a*36+3}px;width:${(b-a+1)*36-6}px" data-action="detail" data-id="${r.id}">${esc(companyFor(state,r)?.companyName||r.name)}</button>`:''}${incoming.map(d=>`<span class="timeline-connection" style="left:${left+a*36+5}px">${icon('link',9)} ${esc(state.deals.find(x=>x.id===d.sourceId)?.name||'선행 업무')} 종료 후${d.offset?' '+d.offset+' '+(d.unit==='DAY'?'일':d.unit==='HOUR'?'시간':'분'):''}</span>`).join('')}</div>`;}).join('')}</div>`;
}
function renderDashboard(){return `<div class="dashboard"><div class="dashboard-title"><div><h1>업무의 흐름을 한곳에서</h1><p>기존 보기를 모아 나에게 맞는 업무 요약을 만들어 보세요.</p></div><button class="button" data-action="add-widget">${icon('plus',14)}보기 추가</button></div><div class="widget-grid">${state.widgets.filter(w=>!w.hidden).map(w=>{const view=state.views.find(v=>v.id===w.viewId);if(!view)return '';return `<article class="widget ${w.wide?'wide':''}" data-widget="${w.id}"><header class="widget-head"><span draggable="true" data-widget-drag="${w.id}" title="끌어서 위치 변경">${icon('drag',13)}</span><button class="title" data-action="widget-title" data-id="${w.id}">${esc(w.title||view.name)}</button><button class="icon-btn" data-action="widget-size" data-id="${w.id}" aria-label="위젯 너비 변경">${icon('expand',13)}</button><button class="icon-btn" data-action="choose-view" data-id="${view.id}" aria-label="원본 보기 열기">${icon('arrow',13)}</button><button class="icon-btn" data-action="remove-widget" data-id="${w.id}" aria-label="대시보드에서 위젯 제거">${icon('close',13)}</button></header><div class="widget-content">${view.layout==='board'?renderBoard(view,true):view.layout==='chart'?chartContent(view):renderTable(view,true)}</div></article>`;}).join('')}</div></div>`;}
function renderWorkspace(){
 const view=activeView();$('#workspace').innerHTML=isDashboard()?renderDashboard():view.layout==='board'?renderBoard(view):view.layout==='chart'?renderChart(view):view.layout==='timeline'?renderTimeline(view):renderTable(view);
 if(ui.selected.size&&!isDashboard())$('#workspace').insertAdjacentHTML('beforeend',`<div class="selection-bar">${ui.selected.size}개 선택됨<button data-action="bulk-stage">단계 변경</button><button data-action="deselect">선택 해제</button></div>`);
}
function renderStatus(){const count=isDashboard()?state.widgets.filter(w=>!w.hidden).length:activeRecords().length;$('#status-bar').innerHTML=`<span>${count}${isDashboard()?'개 보기':'개 기록'}</span><span class="status-hint">${isDashboard()?'위젯 제목 옆 손잡이를 끌어 배치를 바꿀 수 있어요.':activeView().layout==='board'?'카드를 다른 열로 끌면 영업 단계가 바뀝니다.':activeView().layout==='table'?'셀을 눌러 바로 수정할 수 있어요.':'변경 내용은 이 브라우저에 저장됩니다.'}</span><span class="right"></span><button data-action="undo" ${history.length?'':'disabled'}>${icon('undo',11)} 되돌리기</button><button data-action="reset">예시 초기화</button>`;}
function render(){renderSidebar();renderHeader();renderBars();renderWorkspace();renderStatus();$('#app').classList.toggle('sidebar-open',ui.mobile);if(!$('.mobile-overlay'))$('#app').insertAdjacentHTML('beforeend','<button class="mobile-overlay" data-action="mobile" aria-label="메뉴 닫기"></button>');if(ui.detailId)renderDetail();}

function closePopover(){ui.popover=null;$('#popover-root').innerHTML='';}
function showPopover(kind,anchor,extra={}){closePopover();const rect=anchor.getBoundingClientRect();ui.popover={kind,rect,...extra};renderPopover();}
function fieldOptions(view,value){return options(getFields(state,view).map(f=>({id:f.id,label:f.label})),value);}
function renderPopover(){
 if(!ui.popover)return;
 const p=ui.popover,view=state.views.find(v=>v.id===p.viewId)||activeView();let content='',wide=false;
 const head=title=>`<div class="popover-head">${title}<button class="icon-btn" data-action="close-popover" aria-label="닫기">${icon('close',13)}</button></div>`;
 if(p.kind==='settings')content=head('보기 설정')+`<label class="config-label">보기 이름</label><input class="config-control" value="${esc(view.name)}" data-action="view-name"><div class="menu-section">보기 방식</div>${layouts.map(l=>`<button class="menu-item ${view.layout===l.id?'selected':''}" data-action="change-layout" data-layout="${l.id}" ${l.id==='board'&&view.sourceId!=='pipeline'||l.id==='timeline'&&view.sourceId==='companies'?'disabled':''}>${icon(l.icon,15)}${l.label}${view.layout===l.id?'<span class="right">'+icon('check',13)+'</span>':''}</button>`).join('')}<div class="menu-divider"></div><button class="menu-item" data-action="properties">${icon('eye',15)}표시할 정보<span class="right">${icon('right',13)}</span></button><button class="menu-item" data-action="filter">${icon('filter',15)}필터<span class="right">${ruleCount(view.filter)}</span></button><button class="menu-item" data-action="sort">${icon('sort',15)}정렬<span class="right">${view.sorts.length}</span></button>${view.layout==='board'?'<button class="menu-item" data-action="group">'+icon('group',15)+'그룹 설정<span class="right">'+icon('right',13)+'</span></button>':''}<div class="menu-divider"></div><button class="menu-item" data-action="duplicate-view">${icon('copy',15)}현재 보기 복제</button><button class="menu-item" data-action="delete-view">${icon('trash',15)}보기 삭제</button>`;
 if(p.kind==='properties')content=head('표시할 정보')+'<div class="popover-sub">현재 보기에서 보일 정보와 순서를 바꿉니다.</div>'+getFields(state,view).map(f=>{const prop=view.props.find(x=>x.fieldId===f.id);return `<div class="field-row">${icon(f.icon,14)}<span class="field-label">${esc(f.label)}<small class="field-source">${esc(f.source)}</small></span>${prop?`<button class="icon-btn" data-action="move-prop" data-field="${f.id}" data-dir="-1" aria-label="${esc(f.label)} 위로">${icon('left',12)}</button><button class="icon-btn" data-action="move-prop" data-field="${f.id}" data-dir="1" aria-label="${esc(f.label)} 아래로">${icon('right',12)}</button>`:''}<input type="checkbox" aria-label="${esc(f.label)} 표시" data-action="toggle-property" data-field="${f.id}" ${prop&&!prop.hidden?'checked':''}></div>`;}).join('')+`<div class="menu-divider"></div>${view.layout==='board'?`<label class="config-label">카드 제목</label><select class="config-control" data-action="card-title">${fieldOptions(view,view.props.find(x=>x.role==='TITLE')?.fieldId||'name')}</select><div class="field-row"><span class="field-label">정보 이름도 함께 표시</span><input type="checkbox" aria-label="카드 정보 이름 표시" data-action="show-labels" ${view.showLabels?'checked':''}></div>`:''}<button class="menu-item" data-action="new-field">${icon('plus',14)}새로운 정보 추가</button>`;
 if(p.kind==='field'){const f=getField(state,p.fieldId),prop=view.props.find(x=>x.fieldId===p.fieldId);content=head(esc(f.label))+`<label class="config-label">이 보기에서 사용할 이름</label><input class="config-control" value="${esc(prop?.label||f.label)}" data-action="property-label" data-field="${f.id}">${view.layout==='table'?`<label class="config-label">열 너비</label><input class="config-control" type="number" value="${prop?.width||180}" data-action="property-width" data-field="${f.id}">`:''}${f.type==='currency'?`<div class="field-row"><span class="field-label">소수점 표시</span><input type="checkbox" aria-label="소수점 표시" data-action="property-decimals" data-field="${f.id}" ${prop?.decimals?'checked':''}></div>`:''}<div class="menu-divider"></div><button class="menu-item" data-action="hide-property" data-field="${f.id}">${icon('eye',14)}이 보기에서 숨기기</button><button class="menu-item" data-action="sort-field" data-field="${f.id}" data-direction="ASC">${icon('sort',14)}오름차순 정렬</button><button class="menu-item" data-action="sort-field" data-field="${f.id}" data-direction="DESC">${icon('sort',14)}내림차순 정렬</button>`;}
 if(p.kind==='sort')content=head('정렬')+'<div class="popover-sub">위쪽 기준부터 적용합니다. 같은 값이면 다음 기준으로 정렬합니다.</div>'+view.sorts.map((s,i)=>`<div class="sort-row"><button class="icon-btn" data-action="sort-up" data-id="${s.id}" aria-label="정렬 우선순위 올리기" ${i===0?'disabled':''}>${icon('drag',12)}</button><select aria-label="정렬할 정보" data-action="sort-field-change" data-id="${s.id}">${fieldOptions(view,s.fieldId)}</select><select aria-label="정렬 방향" data-action="sort-direction" data-id="${s.id}"><option value="ASC" ${s.direction==='ASC'?'selected':''}>오름차순</option><option value="DESC" ${s.direction==='DESC'?'selected':''}>내림차순</option></select><button class="icon-btn" data-action="remove-sort" data-id="${s.id}" aria-label="정렬 제거">${icon('close',12)}</button></div>`).join('')+`<div class="popover-footer"><button class="button quiet" data-action="add-sort">${icon('plus',13)}정렬 추가</button><button class="button quiet" data-action="clear-sort">초기화</button></div>`;
 if(p.kind==='filter'){wide=true;content=head('필터')+'<div class="popover-sub">어떤 기록을 볼지 정해 보세요. 조건을 바꾸면 화면에 바로 반영됩니다.</div>'+renderFilterGroup(view,view.filter)+`<div class="popover-footer"><span></span><button class="button quiet" data-action="clear-filters" data-view="${view.id}">전체 초기화</button></div>`;}
 if(p.kind==='group')content=head('그룹 설정')+`<label class="config-label">이 정보를 기준으로 나누기</label><select class="config-control" data-action="group-by">${options(getFields(state,view).filter(f=>f.type==='status').map(f=>({id:f.id,label:f.label})),view.groupBy)}</select><div class="menu-section">열 순서와 표시</div>${boardGroups(state,view).map(g=>`<div class="field-row"><span class="stage-dot" style="background:${g.color}"></span><span class="field-label">${esc(g.label)}</span><button class="icon-btn" data-action="group-up" data-stage="${g.id}" aria-label="${esc(g.label)} 앞으로">${icon('left',12)}</button><button class="icon-btn" data-action="fold-group" data-stage="${g.id}" data-view="${view.id}" aria-label="${esc(g.label)} ${g.folded?'펼치기':'접기'}">${icon(g.folded?'right':'chevron',12)}</button><input type="checkbox" aria-label="${esc(g.label)} 열 표시" data-action="group-visibility" data-stage="${g.id}" ${!g.hidden?'checked':''}></div>`).join('')}<div class="menu-divider"></div><button class="menu-item" data-action="add-stage">${icon('plus',14)}새 단계 추가</button>`;
 if(p.kind==='group-menu'){const g=boardGroups(state,view).find(x=>x.id===p.stage);content=head(esc(g.label))+`<label class="config-label">이 보기의 열 이름</label><input class="config-control" data-action="group-label" data-stage="${g.id}" value="${esc(g.label)}"><button class="menu-item" data-action="fold-group" data-stage="${g.id}" data-view="${view.id}">${icon('chevron',14)}열 접기</button><button class="menu-item" data-action="hide-group" data-stage="${g.id}" data-view="${view.id}">${icon('eye',14)}열 숨기기</button><button class="menu-item" data-action="group-up" data-stage="${g.id}">${icon('left',14)}왼쪽으로 이동</button>`;}
 if(p.kind==='bulk-stage')content=head('선택한 영업의 단계 변경')+stages.map(s=>`<button class="menu-item" data-action="bulk-stage-apply" data-stage="${s.id}"><span class="stage-dot" style="background:${s.color}"></span>${s.label}</button>`).join('');
 $('#popover-root').innerHTML=`<div class="popover ${wide?'wide':''}" role="dialog" aria-label="${p.kind==='properties'?'표시할 정보':p.kind==='filter'?'필터':p.kind==='sort'?'정렬':'보기 설정'}">${content}</div>`;
 const el=$('#popover-root .popover'),width=Math.min(wide?560:330,window.innerWidth-24);el.style.width=width+'px';el.style.left=Math.max(12,Math.min(p.rect.left,window.innerWidth-width-12))+'px';el.style.top=Math.min(p.rect.bottom+7,window.innerHeight-130)+'px';
 el.querySelectorAll('label.config-label').forEach((label,index)=>{const input=label.nextElementSibling;if(input?.matches('input,select,textarea')){input.id=`popover-control-${index}`;label.htmlFor=input.id;}});
}
function renderFilterGroup(view,group,nested=false){return `<div class="filter-group ${nested?'nested':''}"><div class="filter-group-head">아래 조건 중<select aria-label="조건 결합 방식" data-action="filter-operator" data-id="${group.id}"><option value="AND" ${group.operator==='AND'?'selected':''}>모두 만족</option><option value="OR" ${group.operator==='OR'?'selected':''}>하나라도 만족</option></select>하는 기록${nested?`<button class="icon-btn" style="margin-left:auto" data-action="remove-filter" data-id="${group.id}" aria-label="그룹 제거">${icon('close',12)}</button>`:''}</div>${group.rules.map(r=>{
 if(r.rules)return renderFilterGroup(view,r,true);
 const field=getField(state,r.fieldId),ops=['currency','number','date'].includes(field?.type)?[{id:'gte',label:'이상'},{id:'lte',label:'이하'},{id:'eq',label:'같음'},{id:'empty',label:'비어 있음'}]:[{id:'eq',label:'같음'},{id:'neq',label:'다름'},{id:'contains',label:'포함'},{id:'empty',label:'비어 있음'}];
 return `<div class="filter-rule"><select class="filter-field" aria-label="필터 정보" data-action="filter-field" data-id="${r.id}">${fieldOptions(view,r.fieldId)}</select><select class="filter-op" aria-label="비교 방법" data-action="filter-op" data-id="${r.id}">${options(ops,r.op)}</select>${r.op==='empty'?'':field?.options?`<select class="filter-value" aria-label="비교 값" data-action="filter-value" data-id="${r.id}">${options(field.options,r.value)}</select>`:`<input class="filter-value" aria-label="비교 값" type="${['currency','number'].includes(field?.type)?'number':field?.type==='date'?'date':'text'}" data-action="filter-value" data-id="${r.id}" value="${esc(r.value)}" placeholder="값 입력">`}${field?.type==='multiselect'?`<select class="filter-op" aria-label="여러 값 비교" data-action="filter-match" data-id="${r.id}"><option value="ANY" ${r.matchMode!=='ALL'?'selected':''}>하나 이상</option><option value="ALL" ${r.matchMode==='ALL'?'selected':''}>모든 값</option></select>`:''}<button class="icon-btn" data-action="remove-filter" data-id="${r.id}" aria-label="조건 제거">${icon('close',12)}</button></div>`;
 }).join('')}<div class="filter-actions"><button class="button quiet small" data-action="add-filter" data-parent="${group.id}">${icon('plus',11)}조건 추가</button><button class="button quiet small" data-action="add-filter-group" data-parent="${group.id}">${icon('plus',11)}조건 그룹</button></div></div>`;}

function closeDetail(){ui.detailId=null;$('#detail-root').innerHTML='';}
function openDetail(id,source){ui.detailId=id;ui.detailSource=source||activeView().sourceId;closePopover();renderDetail();}
function editControl(field,record,action='detail-value'){
 const value=field.id==='company'?record.companyId:record[field.id]??'',attrs=`data-action="${action}" data-field="${field.id}" data-id="${record.id}" data-source="${ui.detailSource||activeView().sourceId}"`;
 if(field.id==='company')return `<select aria-label="${esc(field.label)}" ${attrs}>${options(state.companies.map(c=>({id:c.id,label:c.companyName})),value)}</select>`;
 if(field.options)return `<select aria-label="${esc(field.label)}" ${attrs}>${options(field.options,value)}</select>`;
 return `<input aria-label="${esc(field.label)}" ${attrs} type="${['currency','number'].includes(field.type)?'number':field.type==='date'?'date':'text'}" value="${esc(Array.isArray(value)?value.join(', '):value)}">`;
}
function renderDetail(){
 const record=recordById(ui.detailId,ui.detailSource);if(!record){closeDetail();return;}
 const view=state.views.find(v=>v.sourceId===ui.detailSource)||activeView(),fields=getFields(state,view).filter(f=>!['name','companyName','industry'].includes(f.id));
 $('#detail-root').innerHTML=`<aside class="detail-panel" aria-label="기록 상세"><div class="detail-head"><span>${ui.detailSource==='companies'?'회사':'영업 기회'} 상세</span><button class="icon-btn" data-action="close-detail" aria-label="상세 닫기">${icon('close',16)}</button></div><div class="detail-body"><div class="detail-company">${companyMark(record)}${esc(record.companyName||companyFor(state,record)?.companyName||'영업 기회')}</div><textarea class="detail-title" aria-label="기록 이름" data-action="detail-value" data-id="${record.id}" data-field="${ui.detailSource==='companies'?'companyName':'name'}" data-source="${ui.detailSource}">${esc(record.name||record.companyName)}</textarea>${fields.map(f=>`<div class="detail-property"><label>${icon(f.icon,14)}${esc(f.label)}</label>${editControl(f,record)}</div>`).join('')}<div class="detail-section"><h3>메모</h3><textarea class="detail-notes" aria-label="메모" placeholder="대화 내용이나 다음 할 일을 남겨 보세요." data-action="detail-notes" data-id="${record.id}" data-source="${ui.detailSource}">${esc(record.notes||'')}</textarea></div>${ui.detailSource!=='companies'?`<div class="detail-section"><h3>선행 업무</h3>${state.dependencies.filter(d=>d.targetId===record.id).map(d=>`<div class="dependency-chip">${icon('link',13)}<span>${esc(state.deals.find(r=>r.id===d.sourceId)?.name||'')}<br><small>종료 후 ${d.offset} ${d.unit==='DAY'?'일':d.unit==='HOUR'?'시간':'분'}</small></span><button class="icon-btn" data-action="remove-dependency" data-id="${d.id}" aria-label="업무 연결 제거">${icon('close',12)}</button></div>`).join('')}<button class="button quiet small" data-action="add-dependency" data-id="${record.id}">${icon('plus',12)}선행 업무 연결</button></div>`:''}</div></aside>`;
}
function openDialog(kind,extra={}){
 closePopover();ui.dialogKind=kind;ui.dialogExtra=extra;let title='',description='',body='',submit='저장';
 if(kind==='new-view'){ui.newLayout='table';title='새 보기 만들기';description='같은 기록을 원하는 방식으로 볼 수 있어요.';submit='보기 만들기';body=`<div class="form-row"><label class="form-label" for="view-name">보기 이름</label><input class="form-input" id="view-name" name="name" placeholder="예: 이번 주 진행할 영업" required maxlength="80"></div><div class="form-row"><label class="form-label">어떻게 볼까요?</label><div class="layout-options">${layouts.map(l=>`<button type="button" class="layout-option ${l.id==='table'?'selected':''}" data-action="new-layout" data-layout="${l.id}" ${l.id==='board'&&activeView().sourceId!=='pipeline'||l.id==='timeline'&&activeView().sourceId==='companies'?'disabled':''}>${icon(l.icon,20)}<strong>${l.label}</strong><p>${l.description}</p></button>`).join('')}</div></div><div class="tip">현재 ${nameFor(activeView())}의 기록을 사용합니다. 표시 정보와 조건은 만든 뒤에도 바꿀 수 있어요.</div>`;}
 if(kind==='new-record'){const view=activeView();title=view.sourceId==='companies'?'회사 추가':'새 영업 추가';description='필요한 정보부터 간단하게 시작하세요.';submit='추가';body=view.sourceId==='companies'?`<div class="form-row"><label class="form-label" for="record-name">회사 이름</label><input class="form-input" id="record-name" name="name" required placeholder="예: 새봄 컴퍼니"></div><div class="form-row"><label class="form-label">웹사이트</label><input class="form-input" name="domain" placeholder="예: saebom.co"></div>`:`<div class="form-row"><label class="form-label" for="record-name">영업 기회명</label><input class="form-input" id="record-name" name="name" required placeholder="예: 새봄 연간 계약"></div><div class="form-row"><label class="form-label">고객사</label><select class="form-input" name="companyId">${options(state.companies.map(c=>({id:c.id,label:c.companyName})),state.companies[0]?.id)}</select></div><div class="form-grid"><div class="form-row"><label class="form-label">예상 매출 · 원</label><input class="form-input" name="amount" type="number" placeholder="금액 입력"></div><div class="form-row"><label class="form-label">영업 단계</label><select class="form-input" name="stage">${options(getField(state,'stage').options,extra.stage||'new')}</select></div></div><div class="form-row"><label class="form-label">담당자</label><select class="form-input" name="owner">${options(owners,'jason')}</select></div>`;}
 if(kind==='new-field'){title='필요한 정보 추가';description='현재 기록에 저장할 새로운 정보를 만듭니다.';submit='정보 추가';body=`<div class="form-row"><label class="form-label">정보 이름</label><input class="form-input" name="name" placeholder="예: 다음 연락일" required maxlength="80"></div><div class="form-row"><label class="form-label">정보 유형</label><select class="form-input" name="type"><option value="text">텍스트</option><option value="number">숫자</option><option value="currency">금액</option><option value="date">날짜</option></select></div><div class="tip">추가한 정보는 이 보기에도 바로 표시됩니다.</div>`;}
 if(kind==='add-stage'){title='새 영업 단계';description='업무 흐름에 맞는 단계를 추가하세요.';submit='단계 추가';body='<div class="form-row"><label class="form-label">단계 이름</label><input class="form-input" name="name" required placeholder="예: 기술 검토" maxlength="40"></div>';}
 if(kind==='add-widget'){title='대시보드에 보기 추가';description='이미 만들어 둔 보기를 선택하세요.';submit='추가';body=`<div class="form-row"><label class="form-label">표시할 보기</label><select class="form-input" name="viewId">${options(state.views.filter(v=>v.layout!=='timeline').map(v=>({id:v.id,label:v.name})),state.views[0].id)}</select></div><div class="form-row"><label class="form-label">대시보드에서 사용할 제목</label><input class="form-input" name="name" placeholder="원래 보기 이름 사용"></div>`;}
 if(kind==='widget-title'){title='위젯 제목';description='이 대시보드에 표시할 이름을 바꿉니다.';body=`<div class="form-row"><input class="form-input" name="name" required value="${esc(state.widgets.find(w=>w.id===extra.id)?.title)}"></div>`;}
 if(kind==='add-dependency'){title='선행 업무 연결';description='이 업무에 앞서 진행할 업무와 시간 간격을 지정하세요.';submit='연결';body=`<div class="form-row"><label class="form-label">선행 업무</label><select class="form-input" name="sourceId">${options(state.deals.filter(r=>r.id!==extra.id).map(r=>({id:r.id,label:r.name})),state.deals.find(r=>r.id!==extra.id)?.id)}</select></div><div class="form-grid"><div class="form-row"><label class="form-label">종료 후 시간 간격</label><input class="form-input" type="number" step="any" name="offset" value="0"></div><div class="form-row"><label class="form-label">단위</label><select class="form-input" name="unit"><option value="DAY">일</option><option value="HOUR">시간</option><option value="MINUTE">분</option></select></div></div>`;}
 if(kind==='quick-search'){title='빠르게 찾기';description='회사나 영업 기회 이름을 검색하세요.';body='<input class="form-input" id="quick-query" placeholder="어떤 기록을 찾고 있나요?" aria-label="전체 기록 검색"><div class="search-results" id="quick-results"></div>';submit=null;}
 if(kind==='help'){title='직접 눌러보는 OneHand CRM';description='표와 보드를 바꾸면서 보기의 사용감을 확인해 보세요.';body='<ol class="help-list"><li>상단의 전체 영업과 단계별 보드를 전환해 보세요.</li><li>보기 설정에서 카드에 보이는 정보를 바꿔보세요.</li><li>필터에서 금액 조건을 추가하거나 조건 그룹을 만들어 보세요.</li><li>카드를 다른 단계로 끌거나, 표의 셀을 직접 수정해 보세요.</li><li>보기 추가로 나만의 표·보드·차트를 만들어 보세요.</li><li>업무 요약에서 보기를 추가하고 위치와 너비를 바꿔보세요.</li><li>영업 일정에서 기록을 열어 선행 업무를 연결해 보세요.</li></ol><div class="tip">예시 데이터로 동작하는 UX 목업입니다. 변경은 이 브라우저에 저장되며 하단의 예시 초기화로 되돌릴 수 있어요.</div>';submit=null;}
 if(kind==='delete-view'){title='이 보기를 삭제할까요?';description='기록은 그대로 유지됩니다. 삭제한 보기는 되돌릴 수 있어요.';body=`<div class="help-card"><h3>${esc(activeView().name)}</h3><p>현재 보기 설정을 삭제합니다.</p></div>`;submit='보기 삭제';}
 const dialog=$('#dialog');dialog.innerHTML=`<form id="modal-form"><header class="modal-head"><div><h2>${title}</h2><p>${description}</p></div><button class="icon-btn" type="button" data-action="close-dialog" aria-label="닫기">${icon('close',16)}</button></header><div class="modal-body">${body}<p id="form-error" class="form-error" role="alert"></p></div><footer class="modal-foot"><button class="button" type="button" data-action="close-dialog">${submit?'취소':'닫기'}</button>${submit?`<button class="button primary" type="submit">${submit}</button>`:''}</footer></form>`;dialog.showModal();
 dialog.querySelectorAll('label.form-label').forEach((label,index)=>{const input=label.parentElement.querySelector('input,select,textarea');if(input){input.id ||= `modal-control-${index}`;label.htmlFor=input.id;}});
 $('#modal-form').addEventListener('submit',submitDialog);
 if(kind==='quick-search'){$('#quick-query').addEventListener('input',e=>renderQuickResults(e.target.value));renderQuickResults('');}
 requestAnimationFrame(()=>dialog.querySelector('input')?.focus());
}
function closeDialog(){if($('#dialog').open)$('#dialog').close();ui.dialogKind=null;}
function renderQuickResults(q){const results=[...state.deals.map(r=>({...r,source:'pipeline',title:r.name,subtitle:companyFor(state,r)?.companyName})),...state.companies.map(r=>({...r,source:'companies',title:r.companyName,subtitle:r.domain}))].filter(r=>!q||(r.title+' '+r.subtitle).toLowerCase().includes(q.toLowerCase())).slice(0,8);$('#quick-results').innerHTML=results.map(r=>`<button type="button" class="search-result" data-action="search-detail" data-id="${r.id}" data-source="${r.source}">${companyMark(r)}<span>${esc(r.title)}<small>${esc(r.subtitle)}</small></span></button>`).join('')||'<p class="popover-sub">검색 결과가 없어요.</p>';}
function submitDialog(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),kind=ui.dialogKind,extra=ui.dialogExtra,view=activeView();
 if('name' in values&&kind!=='add-widget'&&!values.name.trim()){$('#form-error').textContent='이름을 입력해 주세요.';return;}
 if(kind==='new-view'){mutate(()=>newView(state,values.name.trim(),ui.newLayout,view.sourceId),'새 보기를 만들었어요.');}
 if(kind==='new-record'){mutate(()=>{if(view.sourceId==='companies')state.companies.push({id:newId('company'),companyName:values.name.trim(),domain:values.domain||'',companyIndustry:[],contact:'',initial:values.name.trim()[0],color:'#e7ebf6'});else state.deals.push({id:newId('record'),name:values.name.trim(),companyId:values.companyId,amount:Number(values.amount)||0,stage:values.stage,owner:values.owner,start:'2026-10-13',end:'2026-10-27',notes:''});},'새 기록을 추가했어요.');}
 if(kind==='new-field'){mutate(()=>{const id=newId('field');state.fields.push({id,label:values.name.trim(),type:values.type,icon:values.type==='date'?'date':values.type==='number'||values.type==='currency'?'number':'text',source:'업무 정보',scopes:view.sourceId==='companies'?['companies']:['pipeline','sales']});view.props.push({fieldId:id,hidden:false,role:'BODY',width:180});},'새 정보를 추가했어요.');}
 if(kind==='add-stage'){mutate(()=>{const id=newId('stage');getField(state,'stage').options.push({id,label:values.name.trim(),color:'#7c9bc9',tint:'#edf3fc'});view.groupOrder.push(id);},'새 단계를 추가했어요.');}
 if(kind==='add-widget')mutate(()=>{const linked=state.views.find(v=>v.id===values.viewId);state.widgets.push({id:newId('widget'),viewId:values.viewId,title:values.name.trim()||linked.name,wide:false});},'대시보드에 보기를 추가했어요.');
 if(kind==='widget-title')mutate(()=>state.widgets.find(w=>w.id===extra.id).title=values.name.trim(),'위젯 제목을 바꿨어요.');
 if(kind==='add-dependency'){const edges=[...state.dependencies,{sourceId:values.sourceId,targetId:extra.id}],visit=(id,target,seen=new Set())=>{if(id===target)return true;if(seen.has(id))return false;seen.add(id);return edges.filter(e=>e.sourceId===id).some(e=>visit(e.targetId,target,seen));};if(state.dependencies.some(d=>d.sourceId===values.sourceId&&d.targetId===extra.id)){$('#form-error').textContent='이미 연결된 업무예요.';return;}if(visit(extra.id,values.sourceId)){$('#form-error').textContent='업무가 서로를 기다리는 연결은 만들 수 없어요.';return;}mutate(()=>state.dependencies.push({id:newId('dependency'),sourceId:values.sourceId,targetId:extra.id,type:'FS',offset:Number(values.offset)||0,unit:values.unit}),'선행 업무를 연결했어요.');}
 if(kind==='delete-view'){if(state.views.filter(v=>v.sourceId===view.sourceId).length===1){$('#form-error').textContent='기본 보기 하나는 남겨주세요.';return;}mutate(()=>{state.views=state.views.filter(v=>v.id!==view.id);state.widgets=state.widgets.filter(w=>w.viewId!==view.id);state.activeView=state.views.find(v=>v.sourceId===view.sourceId).id;},'보기를 삭제했어요.');}
 closeDialog();
}
function startCellEdit(button){const fieldId=button.dataset.field,record=recordById(button.dataset.id,button.dataset.source),field=getField(state,fieldId);if(!record||!field)return;const td=button.closest('td');if(!td)return;td.innerHTML=editControl(field,record,'inline-value');const input=td.querySelector('input,select');input.classList.add('cell-editor');input.focus();if(input.select)input.select();let done=false;const save=()=>{if(done)return;done=true;const value=input.value,previous=fieldId==='company'?record.companyId:record[fieldId];if(String(previous??'')!==value)mutate(()=>setValue(state,record,fieldId,value),'값을 저장했어요.');else renderWorkspace();};input.addEventListener('blur',save);if(input.tagName==='SELECT')input.addEventListener('change',save);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();save();}if(e.key==='Escape'){done=true;renderWorkspace();}});}

document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');
 if(!target){if(ui.popover&&!event.target.closest('.popover'))closePopover();return;}
 const a=target.dataset.action,d=target.dataset,view=state.views.find(v=>v.id===d.view)||activeView(),p=ui.popover;
 if(['select-record','select-all','toggle-property','show-labels','property-decimals','group-visibility','filter-operator','filter-field','filter-op','filter-value','filter-match','sort-field-change','sort-direction','card-title','group-by','view-name','property-label','property-width','group-label','detail-value','detail-notes','inline-value'].includes(a))return;
 const pop=(kind,extra={})=>showPopover(kind,target,extra);
 if(a==='choose-view'){chooseView(d.id);return;}
 if(a==='source'){chooseSource(d.id);return;}
 if(a==='dashboard'){state.activeView='dashboard';ui.search='';ui.mobile=false;closePopover();closeDetail();persist();render();return;}
 if(a==='mobile'){ui.mobile=!ui.mobile;$('#app').classList.toggle('sidebar-open',ui.mobile);return;}
 if(a==='new-view'||a==='new-record'||a==='new-field'||a==='add-stage'||a==='add-widget'||a==='quick-search'||a==='help'||a==='delete-view'){openDialog(a,{stage:d.stage});return;}
 if(a==='widget-title'){openDialog(a,{id:d.id});return;}
 if(a==='settings'||a==='filter'||a==='sort'||a==='group'||a==='properties'||a==='bulk-stage'){pop(a);return;}
 if(a==='field-menu'){pop('field',{fieldId:d.field,viewId:d.view});return;}
 if(a==='group-menu'){pop(a,{stage:d.stage,viewId:d.view});return;}
 if(a==='close-popover'){closePopover();return;}
 if(a==='close-dialog'){closeDialog();return;}
 if(a==='close-detail'){closeDetail();return;}
 if(a==='detail'){openDetail(d.id,d.source);return;}
 if(a==='search-detail'){closeDialog();chooseSource(d.source);openDetail(d.id,d.source);return;}
 if(a==='edit-cell'){closePopover();startCellEdit(target);return;}
 if(a==='undo'){undo();return;}
 if(a==='reset'){mutate(()=>{state=initialState();ui.search='';ui.selected.clear();ui.detailId=null;closePopover();},'예시 데이터로 초기화했어요.');return;}
 if(a==='new-layout'){ui.newLayout=d.layout;document.querySelectorAll('.layout-option').forEach(el=>el.classList.toggle('selected',el.dataset.layout===d.layout));return;}
 if(a==='change-layout'){mutate(()=>view.layout=d.layout);closePopover();return;}
 if(a==='duplicate-view'){mutate(()=>{const clone=JSON.parse(JSON.stringify(view));clone.id=newId('view');clone.name=view.name+' 복사본';state.views.push(clone);state.activeView=clone.id;},'현재 보기를 복제했어요.');closePopover();return;}
 if(a==='move-prop'){const i=view.props.findIndex(x=>x.fieldId===d.field),to=i+Number(d.dir);if(to>=0&&to<view.props.length)mutate(()=>{const [prop]=view.props.splice(i,1);view.props.splice(to,0,prop);});renderPopover();return;}
 if(a==='hide-property'){mutate(()=>view.props.find(x=>x.fieldId===d.field).hidden=true,'이 보기에서 정보를 숨겼어요.');closePopover();return;}
 if(a==='sort-field'){mutate(()=>view.sorts=[{id:newId('sort'),fieldId:d.field,direction:d.direction}]);closePopover();return;}
 if(a==='add-sort'){mutate(()=>view.sorts.push({id:newId('sort'),fieldId:getFields(state,view).find(f=>!view.sorts.some(s=>s.fieldId===f.id))?.id||'name',direction:'ASC'}));renderPopover();return;}
 if(a==='remove-sort'){mutate(()=>view.sorts=view.sorts.filter(s=>s.id!==d.id));renderPopover();return;}
 if(a==='clear-sort'){mutate(()=>view.sorts=[]);renderPopover();return;}
 if(a==='sort-up'){const i=view.sorts.findIndex(s=>s.id===d.id);if(i>0)mutate(()=>[view.sorts[i-1],view.sorts[i]]=[view.sorts[i],view.sorts[i-1]]);renderPopover();return;}
 if(a==='add-filter'){mutate(()=>findRule(view.filter,d.parent).rules.push({id:newId('condition'),fieldId:view.sourceId==='companies'?'companyName':'amount',op:view.sourceId==='companies'?'contains':'gte',value:view.sourceId==='companies'?'':1000000,matchMode:'ANY'}));renderPopover();return;}
 if(a==='add-filter-group'){mutate(()=>findRule(view.filter,d.parent).rules.push({id:newId('group'),operator:'OR',rules:[{id:newId('condition'),fieldId:view.sourceId==='pipeline'?'stage':view.sourceId==='companies'?'companyName':'name',op:'eq',value:view.sourceId==='pipeline'?'proposal':'',matchMode:'ANY'}]}));renderPopover();return;}
 if(a==='remove-filter'){mutate(()=>removeRule(view.filter,d.id));renderPopover();return;}
 if(a==='clear-filters'){mutate(()=>{view.filter.rules=[];ui.search='';});if(p)renderPopover();return;}
 if(a==='fold-group'){mutate(()=>{view.groupSettings[d.stage]??={};view.groupSettings[d.stage].folded=!view.groupSettings[d.stage].folded;});if(p?.kind==='group')renderPopover();else closePopover();return;}
 if(a==='hide-group'){mutate(()=>{view.groupSettings[d.stage]??={};view.groupSettings[d.stage].hidden=true;});closePopover();return;}
 if(a==='group-up'){const i=view.groupOrder.indexOf(d.stage);if(i>0)mutate(()=>[view.groupOrder[i-1],view.groupOrder[i]]=[view.groupOrder[i],view.groupOrder[i-1]]);if(p?.kind==='group')renderPopover();else closePopover();return;}
 if(a==='deselect'){ui.selected.clear();renderWorkspace();return;}
 if(a==='bulk-stage-apply'){mutate(()=>state.deals.filter(r=>ui.selected.has(r.id)).forEach(r=>r.stage=d.stage),'선택한 영업의 단계를 바꿨어요.');ui.selected.clear();closePopover();renderWorkspace();return;}
 if(a==='chart-stage'){const board=state.views.find(v=>v.layout==='board'&&v.sourceId==='pipeline');if(!board)return;mutate(()=>{board.filter.rules=[{id:newId('condition'),fieldId:'stage',op:'eq',value:d.stage}];state.activeView=board.id;state.sourceId='pipeline';ui.search='';});return;}
 if(a==='chart-industry'){const table=state.views.find(v=>v.layout==='table'&&v.sourceId==='companies');if(table)mutate(()=>{table.filter.rules=[{id:newId('condition'),fieldId:'companyIndustry',op:'contains',value:d.value,matchMode:'ANY'}];state.activeView=table.id;state.sourceId='companies';ui.search='';});return;}
 if(a==='widget-size'){mutate(()=>{const w=state.widgets.find(w=>w.id===d.id);w.wide=!w.wide;});return;}
 if(a==='remove-widget'){mutate(()=>state.widgets=state.widgets.filter(w=>w.id!==d.id),'대시보드에서 보기를 제거했어요.');return;}
 if(a==='timeline-shift'){ui.timelineStart=new Date(new Date(ui.timelineStart+'T00:00:00Z').getTime()+Number(d.days)*86400000).toISOString().slice(0,10);renderWorkspace();return;}
 if(a==='add-dependency'){openDialog(a,{id:d.id});return;}
 if(a==='remove-dependency'){mutate(()=>state.dependencies=state.dependencies.filter(x=>x.id!==d.id),'업무 연결을 제거했어요.');return;}
});
document.addEventListener('change',event=>{
 const el=event.target,d=el.dataset,a=d.action,view=state.views.find(v=>v.id===ui.popover?.viewId)||activeView();
 if(!a||a==='inline-value')return;
 if(a==='select-record'){el.checked?ui.selected.add(d.id):ui.selected.delete(d.id);renderWorkspace();renderStatus();return;}
 if(a==='select-all'){ui.selected=new Set(el.checked?activeRecords().map(r=>r.id):[]);renderWorkspace();return;}
 if(a==='toggle-property'){mutate(()=>{const existing=view.props.find(p=>p.fieldId===d.field);if(existing)existing.hidden=!el.checked;else view.props.push({fieldId:d.field,hidden:false,role:'BODY',width:180});});renderPopover();return;}
 if(a==='show-labels'){mutate(()=>view.showLabels=el.checked);return;}
 if(a==='view-name'){if(el.value.trim())mutate(()=>view.name=el.value.trim());return;}
 if(a==='property-label'){mutate(()=>view.props.find(p=>p.fieldId===d.field).label=el.value.trim()||null);return;}
 if(a==='property-width'){if(Number(el.value)>0)mutate(()=>view.props.find(p=>p.fieldId===d.field).width=Number(el.value));return;}
 if(a==='property-decimals'){mutate(()=>view.props.find(p=>p.fieldId===d.field).decimals=el.checked);return;}
 if(a==='card-title'){mutate(()=>{if(!view.props.some(p=>p.fieldId===el.value))view.props.unshift({fieldId:el.value,hidden:false,role:'TITLE',width:180});view.props.forEach(p=>{p.role=p.fieldId===el.value?'TITLE':'BODY';if(p.fieldId===el.value)p.hidden=false;});});return;}
 if(a==='sort-field-change'||a==='sort-direction'){mutate(()=>view.sorts.find(s=>s.id===d.id)[a==='sort-field-change'?'fieldId':'direction']=el.value);return;}
 if(a.startsWith('filter-')){const rule=findRule(view.filter,d.id);if(!rule)return;mutate(()=>{if(a==='filter-operator')rule.operator=el.value;if(a==='filter-field'){rule.fieldId=el.value;rule.value=getField(state,el.value)?.options?.[0]?.id||'';rule.op='eq';}if(a==='filter-op')rule.op=el.value;if(a==='filter-value')rule.value=el.value;if(a==='filter-match')rule.matchMode=el.value;});if(a!=='filter-value')renderPopover();return;}
 if(a==='group-by'){mutate(()=>view.groupBy=el.value);return;}
 if(a==='group-visibility'){mutate(()=>{view.groupSettings[d.stage]??={};view.groupSettings[d.stage].hidden=!el.checked;});return;}
 if(a==='group-label'){mutate(()=>{view.groupSettings[d.stage]??={};if(el.value.trim())view.groupSettings[d.stage].label=el.value.trim();else delete view.groupSettings[d.stage].label;});return;}
 if(a==='detail-value'){const record=recordById(d.id,d.source);if(record)mutate(()=>setValue(state,record,d.field,el.value),'변경사항을 저장했어요.');return;}
 if(a==='detail-notes'){const record=recordById(d.id,d.source);if(record)mutate(()=>record.notes=el.value,'메모를 저장했어요.');return;}
});
document.addEventListener('dragstart',event=>{
 const record=event.target.closest('[data-record-drag]'),group=event.target.closest('[data-group-drag]'),widget=event.target.closest('[data-widget-drag]'),field=event.target.closest('th[data-field-id]');
 if(record){event.dataTransfer.setData('application/x-onehand-record',record.dataset.recordDrag);record.classList.add('dragging');}
 else if(group){event.dataTransfer.setData('application/x-onehand-group',group.dataset.groupDrag);event.dataTransfer.setData('application/x-onehand-view',group.closest('[data-view]').dataset.view);}
 else if(widget)event.dataTransfer.setData('application/x-onehand-widget',widget.dataset.widgetDrag);
 else if(field){event.dataTransfer.setData('application/x-onehand-field',field.dataset.fieldId);}
});
document.addEventListener('dragover',event=>{const column=event.target.closest('.board-column'),widget=event.target.closest('.widget'),field=event.target.closest('th[data-field-id]');if(column||widget||field){event.preventDefault();if(column)column.classList.add('drop-target');if(widget)widget.classList.add('drag-over');}});
document.addEventListener('dragleave',event=>{const target=event.target.closest('.board-column,.widget');if(target&&!target.contains(event.relatedTarget))target.classList.remove('drop-target','drag-over');});
document.addEventListener('dragend',()=>document.querySelectorAll('.dragging,.drop-target,.drag-over').forEach(el=>el.classList.remove('dragging','drop-target','drag-over')));
document.addEventListener('drop',event=>{
 const id=event.dataTransfer.getData('application/x-onehand-record'),groupId=event.dataTransfer.getData('application/x-onehand-group'),widgetId=event.dataTransfer.getData('application/x-onehand-widget'),fieldId=event.dataTransfer.getData('application/x-onehand-field');
 const column=event.target.closest('.board-column'),widget=event.target.closest('.widget'),field=event.target.closest('th[data-field-id]');
 if(id&&column){event.preventDefault();const record=state.deals.find(r=>r.id===id),view=state.views.find(v=>v.id===column.dataset.view);if(record&&view&&record[view.groupBy]!==column.dataset.stage)mutate(()=>record[view.groupBy]=column.dataset.stage,'영업 단계를 변경했어요.');}
 if(groupId&&column){event.preventDefault();const view=state.views.find(v=>v.id===column.dataset.view),from=view.groupOrder.indexOf(groupId),to=view.groupOrder.indexOf(column.dataset.stage);if(from>=0&&to>=0&&from!==to)mutate(()=>{view.groupOrder.splice(from,1);view.groupOrder.splice(to,0,groupId);},'열 순서를 바꿨어요.');}
 if(widgetId&&widget){event.preventDefault();const from=state.widgets.findIndex(w=>w.id===widgetId),to=state.widgets.findIndex(w=>w.id===widget.dataset.widget);if(from>=0&&to>=0&&from!==to)mutate(()=>{const [w]=state.widgets.splice(from,1);state.widgets.splice(to,0,w);},'위젯 위치를 바꿨어요.');}
 if(fieldId&&field){event.preventDefault();const view=activeView(),from=view.props.findIndex(p=>p.fieldId===fieldId),to=view.props.findIndex(p=>p.fieldId===field.dataset.fieldId);if(from>=0&&to>=0&&from!==to)mutate(()=>{const [p]=view.props.splice(from,1);view.props.splice(to,0,p);},'열 순서를 바꿨어요.');}
 document.querySelectorAll('.drop-target,.drag-over').forEach(el=>el.classList.remove('drop-target','drag-over'));
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('#dialog').open)closeDialog();else if(ui.popover)closePopover();else closeDetail();}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!$('#dialog').open)openDialog('quick-search');}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(event.target.tagName)){event.preventDefault();undo();}});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog'))closeDialog();});
window.addEventListener('resize',()=>{closePopover();if(activeView().layout==='timeline')renderWorkspace();});
render();
